import type { ProtocolName } from './config/schema'

// Shared domain types. Node identity (R-S3) is created once per site and survives host
// replacement; it's stored as JSON in `nodes.identity`.

/** AWG obfuscation params produced by a protocol profile, e.g. { Jc: '4', S1: '37', H1: '...' }. */
export type ObfuscationParams = Record<string, string>

export interface KeyPair {
  privateKey: string
  publicKey: string
}

/** A server-side AWG interface: keys, port and obfuscation params generated by the coordinator. */
export interface ServerInterfaceIdentity extends KeyPair {
  listenPort: number
  protocol: ProtocolName
  params: ObfuscationParams
}

export interface LocalIdentity {
  role: 'local'
  /** Client-facing interface. */
  awgc: ServerInterfaceIdentity
  /** Tunnel-client side of the LOCAL→REMOTE tunnel; obfuscation comes from RemoteIdentity.awgt. */
  awgt: KeyPair
}

export interface RemoteIdentity {
  role: 'remote'
  /** Tunnel server; its params are shared by both ends of the tunnel. */
  awgt: ServerInterfaceIdentity & { presharedKey: string }
}

export type NodeIdentity = LocalIdentity | RemoteIdentity

export type NodeRole = 'local' | 'remote'

/** `<site>/local` or `<site>/remote`. */
export function nodeName(site: string, role: NodeRole): string {
  return `${site}/${role}`
}

export type ConfigState = 'active' | 'suspended' | 'revoked'
export type NetworkState = 'ok' | 'degraded' | 'down'

export interface ClientConfigRow {
  id: string
  tg_id: number
  name: string
  address: string
  private_key: string
  public_key: string
  preshared_key: string
  state: ConfigState
  issued_via: 'bot' | 'api'
  delivered_revision: string | null
  api_fetched_at: string | null
  created_at: string
  revoked_at: string | null
}

export interface UserRow {
  tg_id: number
  username: string | null
  status: 'active' | 'suspended'
  membership_checked_at: string | null
  created_at: string
}

export interface DeviceTokenRow {
  token_hash: string
  tg_id: number
  label: string | null
  app_version: string | null
  created_at: string
  last_seen_at: string | null
  revoked_at: string | null
}

export interface HostRow {
  node: string
  address: string
  applied_hash: string | null
  phase: string
  last_ok_at: string | null
  last_error: string | null
  last_error_at: string | null
  consecutive_failures: number
  next_attempt_at: string | null
  health: string
  health_checked_at: string | null
  health_detail: string | null
}

/** A file in a node's desired state (section 7.1). Paths are absolute on the node. */
export interface RenderedFile {
  path: string
  mode: number
  content: string
}
